from typing import List

def dfsSubsequences(s: str) -> List[str]:
    res = []
    path = []

    def dfs(i: int) -> None:
        if i == len(s):
            if path:
                res.append(''.join(path))
            return
        path.append(s[i])        # 选 s[i]
        dfs(i + 1)
        path.pop()               # 不选 s[i]
        dfs(i + 1)

    dfs(0)
    return sorted(res)
